import { run, step } from "zttp:durable";

structural OrderProof<T> = Proof<T,
  | "state_isolated"
  | "fault_covered"
  | "result_safe"
  | "optional_safe"
  | "no_secret_leakage"
  | "no_credential_leakage"
  | "input_validated"
  | "pii_contained"
  | "injection_safe"
  | "deterministic"
  | "idempotent"
  | "retry_safe"
  | "canonical"
  | "cost_bounded"
>;

export function handler(req: Request): OrderProof<Response> {
  const key = req.headers.get("idempotency-key");
  if (key === undefined) {
    return Response.json({ error: "missing idempotency-key" }, { status: 400 });
  }
  return run(key, () => {
    const reservation: { reservationId: string } = step("reserve", () => ({ reservationId: "res-1" }));
    const charge: { chargeId: string } = step("charge", () => ({ chargeId: "chg-1" }));
    return Response.json(
      { reserved: true, charged: true },
      { status: 201 }
    );
  });
}
```

